package com.justenoughmods.achievementguide.integration.companions;
import java.util.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.Recipe;import net.minecraft.nbt.CompoundTag;
/** Observes the common paid native crafting receipt and the actual new unstackable output. */
public final class CompanionQuestHolyCraft {
 public record Pending(ItemStack output){}
 public static final class Click {public final ServerPlayer actor;public final AbstractContainerMenu menu;public final List<ItemStack> before;public final Set<ItemStack> old=Collections.newSetFromMap(new IdentityHashMap<>());public final List<Pending> paid=new ArrayList<>();public Click(ServerPlayer actor,AbstractContainerMenu menu){this.actor=actor;this.menu=menu;var held=held(actor,menu);before=held.stream().map(ItemStack::copy).toList();old.addAll(held);}}
 private static final ThreadLocal<Click> CURRENT=new ThreadLocal<>();private CompanionQuestHolyCraft(){}
 private static List<ItemStack> held(ServerPlayer actor,AbstractContainerMenu menu){var out=new ArrayList<ItemStack>();for(int i=0;i<actor.getInventory().getContainerSize();i++)out.add(actor.getInventory().getItem(i));out.add(menu.getCarried());return out;}
 private static int count(List<ItemStack> stacks,ItemStack sample){return stacks.stream().filter(s->ItemStack.isSameItemSameTags(s,sample)).mapToInt(ItemStack::getCount).sum();}
 public static void begin(ServerPlayer actor,AbstractContainerMenu menu){CURRENT.remove();if(CompanionQuestProof.actor(actor)!=null&&actor.containerMenu==menu&&menu.stillValid(actor)&&menu.slots.size()<=256)CURRENT.set(new Click(actor,menu));}
 public static void crafted(ServerPlayer actor,Recipe<?> recipe,ItemStack output,List<ItemStack> removed){var run=CURRENT.get();if(run==null||run.actor!=actor||recipe==null||removed.isEmpty()||run.paid.size()>=32||output.getCount()!=1||!CompanionQuestProof.holy(output)||actor.level().getRecipeManager().byKey(recipe.getId()).orElse(null)!=recipe)return;var expected=recipe.getResultItem(actor.level().registryAccess());if(expected.getCount()==1&&ItemStack.isSameItemSameTags(output,expected))run.paid.add(new Pending(output.copy()));}
 public static void end(ServerPlayer actor,AbstractContainerMenu menu){var run=CURRENT.get();CURRENT.remove();if(run==null||run.actor!=actor||run.menu!=menu||actor.containerMenu!=menu||CompanionQuestProof.actor(actor)==null||!menu.stillValid(actor))return;var now=held(actor,menu);var allocated=Collections.newSetFromMap(new IdentityHashMap<ItemStack,Boolean>());for(var paid:run.paid){if(count(now,paid.output())-count(run.before,paid.output())<1)continue;for(var actual:now)if(!run.old.contains(actual)&&!allocated.contains(actual)&&actual.getCount()==1&&ItemStack.isSameItemSameTags(actual,paid.output())){var payload=new CompoundTag();payload.putString("native","paid_crafting_result_slot");CompanionQuestStack.put(actual,actor.getUUID(),UUID.randomUUID(),"holy",payload);allocated.add(actual);break;}}}
}
